@push('scripts')<script>$(function(){const element=$('#issue-types-table'),text=$.fn.dataTable.render.text(),table=element.DataTable($.extend(true,{},window.erpDataTableDefaults,{processing:true,serverSide:true,order:[[0,'asc']],ajax:'{{ route('wms.issue-types.data') }}',buttons:[window.erpExcelButton(element)],columns:[{data:'code',name:'code',render:text.display},{data:'name',name:'name',render:text.display},{data:'description',name:'description',render:text.display},{data:'warehouse_label',orderable:false,render:text.display},{data:'status_label',name:'is_active',render:(value,type,row)=>type==='display'?'<span class="badge '+(row.is_active?'app-status-success':'app-status-neutral')+'">'+text.display(value)+'</span>':value},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:(value,type,row)=>{if(type!=='display')return '';let html=row.edit_url?'<a class="btn btn-sm btn-app-soft" href="'+row.edit_url+'" title="แก้ไข" aria-label="แก้ไข '+text.display(row.code)+'"><i class="bx bx-edit" aria-hidden="true"></i></a>':'';if(row.delete_url&&!row.in_use)html+=' <button type="button" class="btn btn-sm btn-app-danger js-issue-type-delete" data-url="'+row.delete_url+'" title="ลบ" aria-label="ลบ '+text.display(row.code)+'"><i class="bx bx-trash" aria-hidden="true"></i></button>';if(row.in_use)html+=' <span class="text-secondary ms-2" title="มีเอกสารใช้งานแล้ว ให้ปิดใช้งานแทน" aria-label="มีเอกสารใช้งานแล้ว"><i class="bx bx-lock-alt" aria-hidden="true"></i></span>';return html;}}]}));window.erpAjaxDelete({button:'.js-issue-type-delete',reload:'#issue-types-table',title:'ลบประเภทการเบิก?',text:'ลบได้เฉพาะประเภทที่ยังไม่ถูกใช้งานกับเอกสาร',confirmButtonText:'ลบ',cancelButtonText:'กลับ'});});</script>@endpush
